import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score

MAX_DRIVERS = 5

def design(feats):
    # Find features with strong effect sizes
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        y1 = feats.x[feats.y == 1, i]
        y0 = feats.x[feats.y == 0, i]
        mean_diff = np.mean(y1) - np.mean(y0)
        t_stat, _ = stats.ttest_ind(y1, y0, equal_var=False)
        effect_sizes.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by effect size
    effect_sizes.sort(key=lambda x: x[2], reverse=True)

    # Check for correlated pairs
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if feats.types[i] == 'clinical' or feats.types[j] == 'clinical':
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                # Normalize pair order
                pair = tuple(sorted([fid1, fid2]))
                correlated_pairs.add(pair)

    # Look for product terms among correlated pairs
    candidates = []
    for fid1, fid2 in correlated_pairs:
        col1 = feats.column(fid1)
        col2 = feats.column(fid2)
        product = feats.x[:,col1] * feats.x[:,col2]

        # Test AUC of product
        auc = roc_auc_score(feats.y, product)
        if auc > 0.55:
            candidates.append((fid1, fid2, auc))

    # Sort by AUC
    candidates.sort(key=lambda x: x[2], reverse=True)

    # Return top product term if exists
    if candidates:
        a, b, _ = candidates[0]
        return Design(
            drivers=(a, b),
            columns=(a, b),
            products=((a, b),),
            loadings={}
        )

    # If no product term found, try single features
    if effect_sizes:
        top_fid = effect_sizes[0][0]
        return Design(
            drivers=(top_fid,),
            columns=(top_fid,),
            products=(),
            loadings={}
        )

    # No mechanism found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

